/**
 * JanSamadhan – Grok AI Analysis Zod Schemas
 * Strictly validates structured responses from Grok API and officer review payloads.
 */

const { z } = require('zod');

// Schema for structured output generated by Grok API
const grokOutputSchema = z.object({
  summary: z
    .string()
    .trim()
    .min(5, 'Summary must be at least 5 characters')
    .max(1000, 'Summary cannot exceed 1000 characters'),
  suggestedCategory: z
    .string()
    .trim()
    .min(2, 'Suggested category is required'),
  categoryConfidence: z
    .number()
    .min(0)
    .max(1)
    .default(0.85),
  categoryReason: z
    .string()
    .trim()
    .optional(),
  severity: z.enum(['LOW', 'MEDIUM', 'HIGH', 'CRITICAL']),
  severityConfidence: z
    .number()
    .min(0)
    .max(1)
    .default(0.85),
  severityReason: z
    .string()
    .trim()
    .min(5, 'Severity reasoning must be at least 5 characters'),
  suggestedDepartment: z
    .string()
    .trim()
    .min(2, 'Suggested department is required'),
  departmentConfidence: z
    .number()
    .min(0)
    .max(1)
    .default(0.85),
  urgency: z.enum(['LOW', 'MEDIUM', 'HIGH', 'URGENT']).default('MEDIUM'),
  solutionSuggestions: z
    .array(
      z.object({
        title: z.string().trim().min(3).max(150),
        description: z.string().trim().min(10).max(1000),
        department: z.string().trim().optional(),
        complexity: z.enum(['LOW', 'MEDIUM', 'HIGH']).default('MEDIUM'),
        benefits: z.string().trim().min(3),
        limitations: z.string().trim().min(3),
      })
    )
    .min(1, 'At least 1 solution suggestion is required')
    .max(5, 'Maximum of 5 solution suggestions allowed'),
  possibleDuplicates: z
    .array(
      z.object({
        reportId: z.string().optional(),
        trackingId: z.string().optional(),
        similarityExplanation: z.string().trim(),
        confidence: z.number().min(0).max(1),
      })
    )
    .default([]),
  requiresHumanReview: z.boolean().default(true),
});

// Schema for government officer review of AI recommendations
const reviewAnalysisSchema = z.object({
  action: z.enum(['ACCEPT', 'EDIT', 'REJECT'], {
    required_error: 'Review action must be ACCEPT, EDIT, or REJECT',
  }),
  notes: z.string().trim().max(1000).optional(),
  editedFields: z
    .object({
      suggestedCategory: z.string().trim().optional(),
      severity: z.enum(['LOW', 'MEDIUM', 'HIGH', 'CRITICAL']).optional(),
      suggestedDepartment: z.string().trim().optional(),
      urgency: z.enum(['LOW', 'MEDIUM', 'HIGH', 'URGENT']).optional(),
    })
    .optional(),
});

// Schema for manual re-analysis request
const triggerAnalysisSchema = z.object({
  forceReanalyze: z.boolean().optional().default(false),
});

module.exports = {
  grokOutputSchema,
  reviewAnalysisSchema,
  triggerAnalysisSchema,
};

